import{_ as a,o as s,c as n,a0 as t}from"./chunks/framework.bcCluOOn.js";const u=JSON.parse('{"title":"Workflows & State Machines","description":"","frontmatter":{},"headers":[],"relativePath":"specification/workflows.md","filePath":"specification/workflows.md"}'),i={name:"specification/workflows.md"};function o(l,e,r,p,c,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="workflows-state-machines" tabindex="-1">Workflows &amp; State Machines <a class="header-anchor" href="#workflows-state-machines" aria-label="Permalink to &quot;Workflows &amp; State Machines&quot;">​</a></h1><p>Many business applications require tracking the state of an entity over time (e.g., an Order moving from <em>Pending</em> to <em>Shipped</em> to <em>Delivered</em>). Traditionally, this involves writing complex boolean flags or status enum checks scattered throughout the codebase.</p><p>AAYU elevates this concept to a first-class citizen using the <code>workflow</code> block, creating a rigid, compiler-enforced state machine attached to an entity.</p><h2 id="defining-a-workflow" tabindex="-1">Defining a Workflow <a class="header-anchor" href="#defining-a-workflow" aria-label="Permalink to &quot;Defining a Workflow&quot;">​</a></h2><p>A workflow is defined using the <code>workflow</code> keyword, named, and explicitly attached to a specific <code>entity</code> using the <code>for</code> keyword.</p><p>Inside the workflow block, the <code>step</code> keyword defines the valid sequential states.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>entity Order.</span></span>
<span class="line"><span>    text customer_name.</span></span>
<span class="line"><span>    number total.</span></span>
<span class="line"><span>end.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>workflow OrderFulfillment for Order.</span></span>
<span class="line"><span>    step Pending.</span></span>
<span class="line"><span>    step Processing.</span></span>
<span class="line"><span>    step Shipped.</span></span>
<span class="line"><span>    step Delivered.</span></span>
<span class="line"><span>    step Cancelled.</span></span>
<span class="line"><span>end.</span></span></code></pre></div><h2 id="compiler-actions" tabindex="-1">Compiler Actions <a class="header-anchor" href="#compiler-actions" aria-label="Permalink to &quot;Compiler Actions&quot;">​</a></h2><p>When the AAYU Compiler encounters a <code>workflow</code>:</p><ol><li><strong>Schema Update</strong>: It automatically injects a <code>status</code> field into the target <code>entity</code> (e.g., <code>Order.status</code>).</li><li><strong>Default State</strong>: It sets the default value of new records to the <em>first</em> defined step (e.g., <code>Pending</code>).</li><li><strong>Validation</strong>: It generates runtime guardrails ensuring that state transitions occur in a valid order (e.g., you cannot move from <code>Pending</code> directly to <code>Delivered</code> without custom override logic, and you cannot assign a status that doesn&#39;t exist in the workflow).</li></ol><h2 id="future-capabilities" tabindex="-1">Future Capabilities <a class="header-anchor" href="#future-capabilities" aria-label="Permalink to &quot;Future Capabilities&quot;">​</a></h2><p>Future revisions of the AAYU specification will introduce transition hooks:</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Proposed future syntax</span></span>
<span class="line"><span>on transition from Processing to Shipped.</span></span>
<span class="line"><span>    run send_shipping_email with order.</span></span>
<span class="line"><span>end.</span></span></code></pre></div>`,13)])])}const f=a(i,[["render",o]]);export{u as __pageData,f as default};
